package com.overheadchatcolor;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(OverheadChatColorConfig.GROUP)
public interface OverheadChatColorConfig extends Config
{
	String GROUP = "overheadchatcolor";

	// ---------------------------------------------------------------- Tick to enable

	@ConfigSection(
		name = "Tick to enable",
		description = "Choose whose overhead chat gets recolored. Unticked groups use the next group that applies "
			+ "(ending with Others), or the game's normal colors if none apply.",
		position = 0
	)
	String enableSection = "enableSection";

	@ConfigItem(
		keyName = "enablePlayer",
		name = "Player (you)",
		description = "Recolor the chat above your own head. Typing a game color like red: or rainbow: still overrides it.",
		section = enableSection,
		position = 0
	)
	default boolean enablePlayer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableOthers",
		name = "Others",
		description = "Recolor every other player who isn't covered by a ticked group below.",
		section = enableSection,
		position = 1
	)
	default boolean enableOthers()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableFriends",
		name = "Friends",
		description = "Recolor players on your friends list.",
		section = enableSection,
		position = 2
	)
	default boolean enableFriends()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableParty",
		name = "Party members",
		description = "Recolor players in your RuneLite party.",
		section = enableSection,
		position = 3
	)
	default boolean enableParty()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableClan",
		name = "Clan",
		description = "Recolor members of your clan.",
		section = enableSection,
		position = 4
	)
	default boolean enableClan()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableFriendsChat",
		name = "Friends chat",
		description = "Recolor members of the friends chat channel you're in.",
		section = enableSection,
		position = 5
	)
	default boolean enableFriendsChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "enableNpcs",
		name = "NPCs",
		description = "Recolor text above NPCs' heads.",
		section = enableSection,
		position = 6
	)
	default boolean enableNpcs()
	{
		return false;
	}

	// ---------------------------------------------------------------- Colors

	@ConfigSection(
		name = "Colors",
		description = "The color used for each group. If a player is in more than one group, the first ticked one wins, "
			+ "in this order: Friends, Party members, Clan, Friends chat, Others.",
		position = 1
	)
	String colorSection = "colorSection";

	@ConfigItem(
		keyName = "ownColor",
		name = "Player (you)",
		description = "Color of the chat above your own head.",
		section = colorSection,
		position = 0
	)
	default Color ownColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "othersColor",
		name = "Others",
		description = "Color of the chat above other players' heads.",
		section = colorSection,
		position = 1
	)
	default Color othersColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "friendsColor",
		name = "Friends",
		description = "Color of the chat above your friends' heads.",
		section = colorSection,
		position = 2
	)
	default Color friendsColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "partyColor",
		name = "Party members",
		description = "Color of the chat above your RuneLite party members' heads.",
		section = colorSection,
		position = 3
	)
	default Color partyColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "clanColor",
		name = "Clan",
		description = "Color of the chat above your clan members' heads.",
		section = colorSection,
		position = 4
	)
	default Color clanColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "friendsChatColor",
		name = "Friends chat",
		description = "Color of the chat above your friends chat members' heads.",
		section = colorSection,
		position = 5
	)
	default Color friendsChatColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}

	@ConfigItem(
		keyName = "npcColor",
		name = "NPCs",
		description = "Color of the text above NPCs' heads.",
		section = colorSection,
		position = 6
	)
	default Color npcColor()
	{
		return OverheadChatColorPlugin.DEFAULT_YELLOW;
	}
}

package com.overheadchatcolor;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ChatboxInput;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;

/**
 * Recolors the text shown above players' and NPCs' heads.
 *
 * Everything here is local: the plugin only rewrites the text that is already
 * on your own screen. It never sends anything to the game, never changes what
 * you type, and other players can't see the colors you pick.
 */
@PluginDescriptor(
	name = "Overhead Chat Color",
	description = "Choose the color of overhead chat for you, friends, party, clan, friends chat, other players and NPCs (only you see it)",
	tags = {"overhead", "chat", "color", "colour", "text", "public", "friends", "clan", "party", "npc"}
)
public class OverheadChatColorPlugin extends Plugin
{
	/** The game's standard overhead chat yellow. */
	static final Color DEFAULT_YELLOW = new Color(0xFFFF00);

	private static final String COLOR_TAG_START = "<col=";

	/** chatType value RuneLite uses for public chat in {@link ChatboxInput}. */
	private static final int PUBLIC_CHAT = 0;

	/**
	 * How many game ticks after you send a message we keep waiting for it to appear
	 * above your head. Stops a missed message from affecting a later one.
	 */
	private static final int NATIVE_COLOR_WINDOW_TICKS = 10;

	/**
	 * Every game color prefix: yellow, red, green, cyan, purple, white, flash1-3, glow1-3,
	 * rainbow, and custom patterns like patternq3q3q3q3. When you type one, the game's color wins.
	 */
	private static final String NATIVE_COLOR_NAMES =
		"yellow|red|green|cyan|purple|white|flash[123]|glow[123]|rainbow|pattern[a-z0-9]{1,8}";
	private static final Pattern NATIVE_COLOR = Pattern.compile(NATIVE_COLOR_NAMES);

	/** Any chat prefix, color or motion (motion-only prefixes like wave: still get your color). */
	private static final Pattern CHAT_PREFIX = Pattern.compile(
		"^\\s*(" + NATIVE_COLOR_NAMES + "|wave2?|shake|scroll|slide):",
		Pattern.CASE_INSENSITIVE);

	@Inject
	private Client client;

	@Inject
	private OverheadChatColorConfig config;

	@Inject
	private PartyService partyService;

	/** Tick when you last sent a public message with a game color prefix, or -1. */
	private int nativeColorSentTick = -1;

	@Provides
	OverheadChatColorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OverheadChatColorConfig.class);
	}

	@Override
	protected void shutDown()
	{
		nativeColorSentTick = -1;
	}

	/**
	 * Watches what you send (read-only) so your own red:, flash1:, glow2: etc. can override the plugin.
	 */
	@Subscribe
	public void onChatboxInput(ChatboxInput event)
	{
		if (event.getChatType() != PUBLIC_CHAT)
		{
			return;
		}

		nativeColorSentTick = usesNativeColor(event.getValue()) ? client.getTickCount() : -1;
	}

	/** Your own messages are handled here, the moment they appear. */
	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		Actor actor = event.getActor();
		if (actor != client.getLocalPlayer())
		{
			// Everyone else is handled in onClientTick.
			return;
		}

		String text = event.getOverheadText();
		if (text == null || text.isEmpty() || text.startsWith(COLOR_TAG_START))
		{
			return;
		}

		if (nativeColorSentTick != -1)
		{
			boolean recent = client.getTickCount() - nativeColorSentTick <= NATIVE_COLOR_WINDOW_TICKS;
			nativeColorSentTick = -1;
			if (recent)
			{
				// You typed a game color like red: or glow2:, so the game's color wins.
				return;
			}
		}

		if (config.enablePlayer())
		{
			applyColor(actor, config.ownColor());
		}
	}

	/**
	 * Other players' and NPCs' text doesn't reliably come through onOverheadTextChanged in a way
	 * that sticks, so every client tick we check everyone on screen and color anything not colored yet.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		recolor(worldView);
		// Players and NPCs on boats and other moving areas live in their own sub-views.
		for (WorldView sub : worldView.worldViews())
		{
			if (sub != null)
			{
				recolor(sub);
			}
		}
	}

	private void recolor(WorldView worldView)
	{
		Player me = client.getLocalPlayer();
		for (Player player : worldView.players())
		{
			if (player != null && player != me)
			{
				applyColor(player, colorFor(player));
			}
		}

		if (config.enableNpcs())
		{
			Color npcColor = config.npcColor();
			for (NPC npc : worldView.npcs())
			{
				if (npc != null)
				{
					applyColor(npc, npcColor);
				}
			}
		}
	}

	/**
	 * The color for another player, or null to leave their text as the game shows it.
	 * If they're in more than one group, the first ticked one wins:
	 * Friends, Party members, Clan, Friends chat, then Others.
	 */
	private Color colorFor(Player player)
	{
		if (config.enableFriends() && player.isFriend())
		{
			return config.friendsColor();
		}
		if (config.enableParty() && isPartyMember(player))
		{
			return config.partyColor();
		}
		if (config.enableClan() && player.isClanMember())
		{
			return config.clanColor();
		}
		if (config.enableFriendsChat() && player.isFriendsChatMember())
		{
			return config.friendsChatColor();
		}
		if (config.enableOthers())
		{
			return config.othersColor();
		}
		return null;
	}

	private boolean isPartyMember(Player player)
	{
		String name = player.getName();
		return name != null && partyService.isInParty() && partyService.getMemberByDisplayName(name) != null;
	}

	private static void applyColor(Actor actor, Color color)
	{
		if (color == null)
		{
			return;
		}

		String text = actor.getOverheadText();
		if (text == null || text.isEmpty() || text.startsWith(COLOR_TAG_START))
		{
			// Nothing to color, or it's already colored.
			return;
		}

		actor.setOverheadText(ColorUtil.wrapWithColorTag(text, color));
	}

	/**
	 * True if the message starts with a game color prefix, including stacked
	 * prefixes like "green:wave:" or "wave:green:".
	 */
	static boolean usesNativeColor(String message)
	{
		if (message == null)
		{
			return false;
		}

		String rest = message;
		for (int i = 0; i < 2; i++)
		{
			Matcher m = CHAT_PREFIX.matcher(rest);
			if (!m.find())
			{
				return false;
			}
			if (NATIVE_COLOR.matcher(m.group(1).toLowerCase()).matches())
			{
				return true;
			}
			rest = rest.substring(m.end());
		}
		return false;
	}
}

package com.overheadchatcolor;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class OverheadChatColorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OverheadChatColorPlugin.class);
		RuneLite.main(args);
	}
}
